package dev.mars.peegeeq.cache.rest.server;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.AriaRole;
import org.junit.jupiter.api.extension.RegisterExtension;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Wave P4 real-browser scenarios for locks, ownership, fencing, and conflicts. */
class ManagementLockBrowserIT {
    @RegisterExtension static final ManagementBrowserPostgresWorker POSTGRES=new ManagementBrowserPostgresWorker();
    @TempDir Path temporaryDirectory;
    private static final List<String>ACTIONS=List.of(
            "state the active database lease scope","show canonical lock columns","list the seeded active lock","show exact namespace","show exact lock key","show fencing token 7","show version 5","show lease expiry","show positive remaining lease","mask owner in inventory","offer lock management","exclude owner token from inventory DOM","exclude owner token from URL",
            "open authoritative lock details","show current version in dialog","show current fencing token in dialog","bound optional reason minimum","bound optional reason maximum","close management cleanly","dismiss management with Escape","offer force release to operators","offer reveal to authorized operators","keep owner masked initially",
            "reveal the owner token exactly","submit a reviewed reveal reason","hide a revealed owner explicitly","clear owner when dialog closes","clear owner when dialog escapes","clear owner on visibility loss","clear owner when management reopens","clear owner on page reload","clear owner on logout","exclude owner from URL after reveal","exclude owner from browser storage","exclude owner from durable audit",
            "reload before force-release confirmation","explain reacquisition conflicts","disable release for blank confirmation","disable release for wrong confirmation","enable release for exact key","cancel force release without mutation","dismiss force release with Escape","reject a stale renewed version","release the exact current lock version");
    static List<ManagementBrowserCase> scenarios(){return java.util.stream.IntStream.range(0,44).mapToObj(i->new ManagementBrowserCase(
            "PW-LOCK-%03d".formatted(i+2),"P4 lock contract: "+ACTIONS.get(i),ManagementBrowserArea.LOCK,i>=23?ManagementBrowserRisk.CRITICAL:ManagementBrowserRisk.HIGH,ACTIONS.get(i),"The packaged console must "+ACTIONS.get(i)+".","Hide owner data, reset PostgreSQL, and close browser, audit, server, and pool resources",ops(i),
            i>=23&&i<=34?Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.HTTP_OPERATION,ManagementBrowserEvidence.DATABASE,ManagementBrowserEvidence.DURABLE_AUDIT,ManagementBrowserEvidence.SENSITIVE_STATE,ManagementBrowserEvidence.RESOURCE_CLEANUP):i>=35?Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.HTTP_OPERATION,ManagementBrowserEvidence.DATABASE,ManagementBrowserEvidence.DURABLE_AUDIT,ManagementBrowserEvidence.RESOURCE_CLEANUP):Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.HTTP_OPERATION,ManagementBrowserEvidence.RESOURCE_CLEANUP))).toList();}
    private static List<String>ops(int i){if(i<13)return List.of("listLocks");if(i<23)return List.of("listLocks","getLock");if(i==31)return List.of("listLocks","getLock","revealLockOwner","deleteLocalSession");if(i<35)return List.of("listLocks","getLock","revealLockOwner");if(i<42)return List.of("listLocks","getLock");return List.of("listLocks","getLock","forceReleaseLock");}

    @ParameterizedTest(name="{0}")@MethodSource("dev.mars.peegeeq.cache.rest.server.ManagementBrowserSelection#lockScenarios")void lockScenario(ManagementBrowserCase s)throws Exception{int i=Integer.parseInt(s.id().substring(s.id().length()-3))-2;ManagementConsolePostgresFixture.run(temporaryDirectory,POSTGRES.postgres(),true,s.operations(),c->{if(i==42)c.diagnostics().expectFailedResponse(412,"/api/v1/setups/{setupId}/namespaces/{encodedNamespace}/locks/{encodedKey}/force-release");if(i==43)c.diagnostics().allowFailedResponse(404,"/api/v1/setups/{setupId}/namespaces/{encodedNamespace}/locks/{encodedKey}");Page p=c.page();p.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Locks").setExact(true)).click();assertThat(p.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Locks").setExact(true))).isVisible();if(i==27)verifyEscapeCleanup(p);else if(i==31)verifyLogoutCleanup(p);else verify(i,c);});}
private static void verifyEscapeCleanup(Page p){Locator d=reveal(p,"");d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).press("Escape");assertThat(d).hasCount(0);assertThat(p.getByText("owner-secret",exact())).hasCount(0);}
    private static void verifyLogoutCleanup(Page p){Locator d=reveal(p,"");d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).click();assertThat(d).hasCount(0);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("End local session")).click();assertThat(p.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Connect to management console"))).isVisible();assertThat(p.getByText("owner-secret",exact())).hasCount(0);}
    private static void verify(int i,ManagementConsolePostgresFixture.Context c)throws Exception{Page p=c.page();switch(i){
        case 0->assertThat(p.getByText("Active database leases",exact())).isVisible();case 1->{Locator headers=p.locator("thead th");assertThat(headers).hasCount(8);assertEquals(List.of("Namespace","Key","Fencing token","Version","Lease expires","Remaining","Owner","Actions"),headers.allTextContents());}case 2->assertThat(row(p)).isVisible();case 3->assertEquals("logical-orders",row(p).locator("td").nth(0).textContent());case 4->assertEquals("lease",row(p).locator("td").nth(1).textContent());case 5->assertEquals("7",row(p).locator("td").nth(2).textContent());case 6->assertEquals("5",row(p).locator("td").nth(3).textContent());case 7->assertFalse(row(p).locator("td").nth(4).textContent().isBlank());case 8->assertTrue(row(p).locator("td").nth(5).textContent().endsWith(" ms"));case 9->assertEquals("Masked",row(p).locator("td").nth(6).textContent());case 10->assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Manage lease"))).isVisible();case 11->assertFalse(p.content().contains("owner-secret"));case 12->assertFalse(p.url().contains("owner-secret"));
case 13->assertThat(manage(p)).isVisible();case 14->assertThat(manage(p)).containsText("Version 5");case 15->assertThat(manage(p)).containsText("fencing token 7");case 16->assertThat(manage(p).getByLabel("Reason (optional)")).hasAttribute("minlength","3");case 17->assertThat(manage(p).getByLabel("Reason (optional)")).hasAttribute("maxlength","240");case 18->{Locator d=manage(p);d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).click();assertThat(d).hasCount(0);}case 19->{Locator d=manage(p);assertThat(d).isVisible();d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).press("Escape");assertThat(d).hasCount(0);}case 20->assertThat(manage(p).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Force release"))).isVisible();case 21->assertThat(manage(p).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Reveal owner"))).isVisible();case 22->{Locator d=manage(p);assertThat(d.getByText("Masked",new Locator.GetByTextOptions().setExact(true))).isVisible();assertFalse(d.textContent().contains("owner-secret"));}
case 23->{reveal(p,"");assertThat(p.getByText("owner-secret",exact())).isVisible();}case 24->{reveal(p,"incident review");assertThat(p.getByText("owner-secret",exact())).isVisible();}case 25->{reveal(p,"");p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Hide owner")).click();assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 26->{Locator d=reveal(p,"");d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).click();assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 27->{Locator d=reveal(p,"");d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).press("Escape");assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 28->{reveal(p,"");p.evaluate("Object.defineProperty(document,'hidden',{value:true,configurable:true});document.dispatchEvent(new Event('visibilitychange'))");assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 29->{Locator d=reveal(p,"");d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Close")).click();manage(p);assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 30->{reveal(p,"");p.reload();assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 31->{reveal(p,"");p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("End local session")).click();assertThat(p.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Connect to management console"))).isVisible();assertThat(p.getByText("owner-secret",exact())).hasCount(0);}case 32->{reveal(p,"");assertFalse(p.url().contains("owner-secret"));}case 33->{reveal(p,"");String state=String.valueOf(p.evaluate("JSON.stringify({local:Object.values(localStorage),session:Object.values(sessionStorage),cookie:document.cookie})"));assertFalse(state.contains("owner-secret"));}case 34->{reveal(p,"audit verification");assertFalse(Files.readString(c.auditPath()).contains("owner-secret"));}
        case 35->assertThat(releaseDialog(p)).isVisible();case 36->assertThat(releaseDialog(p)).containsText("reloaded immediately");case 37->assertThat(releaseButton(releaseDialog(p))).isDisabled();case 38->{Locator d=releaseDialog(p);d.getByLabel("Confirm lock key").fill("wrong");assertThat(releaseButton(d)).isDisabled();}case 39->{Locator d=releaseDialog(p);d.getByLabel("Confirm lock key").fill("lease");assertThat(releaseButton(d)).isEnabled();}case 40->{Locator d=releaseDialog(p);d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Cancel")).click();assertThat(d).hasCount(0);assertThat(p.getByRole(AriaRole.DIALOG,new Page.GetByRoleOptions().setName("Manage lease"))).isVisible();}case 41->{Locator d=releaseDialog(p);assertThat(d.getByLabel("Confirm lock key")).isFocused();p.keyboard().press("Escape");assertThat(d).hasCount(0);}case 42->{Locator d=releaseDialog(p);ManagementConsolePostgresFixture.execute(c.postgres(),"UPDATE peegee_cache.cache_locks SET version=version+1 WHERE namespace='logical-orders' AND lock_key='lease'");d.getByLabel("Confirm lock key").fill("lease");releaseButton(d).click();assertThat(p.getByRole(AriaRole.ALERT)).containsText("VERSION_MISMATCH");assertEquals("1",ManagementConsolePostgresFixture.queryScalar(c.postgres(),"SELECT count(*) FROM peegee_cache.cache_locks WHERE lock_key='lease'"));}case 43->{Locator d=releaseDialog(p);d.getByLabel("Confirm lock key").fill("lease");releaseButton(d).click();assertThat(p.getByRole(AriaRole.STATUS)).containsText("Lock released");assertThat(row(p)).hasCount(0);assertEquals("0",ManagementConsolePostgresFixture.queryScalar(c.postgres(),"SELECT count(*) FROM peegee_cache.cache_locks WHERE lock_key='lease'"));}default->throw new IllegalArgumentException();}}
    private static Locator row(Page p){return p.getByRole(AriaRole.ROW).filter(new Locator.FilterOptions().setHasText("logical-orders")).filter(new Locator.FilterOptions().setHasText("lease"));}
    private static Locator manage(Page p){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Manage lease")).click();return p.getByRole(AriaRole.DIALOG,new Page.GetByRoleOptions().setName("Manage lease"));}
    private static Locator reveal(Page p,String reason){Locator d=manage(p);if(!reason.isEmpty())d.getByLabel("Reason (optional)").fill(reason);d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Reveal owner")).click();assertThat(p.getByText("owner-secret",exact())).isVisible();return d;}
    private static Locator releaseDialog(Page p){Locator d=manage(p);d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Force release")).click();return p.getByRole(AriaRole.DIALOG,new Page.GetByRoleOptions().setName("Release current lock version?"));}private static Locator releaseButton(Locator d){return d.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Release current version"));}private static Page.GetByTextOptions exact(){return new Page.GetByTextOptions().setExact(true);}
}
